package com.aistock.prediction.portfolioquestion;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import com.aistock.common.BusinessException;import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.math.BigDecimal;
import static com.aistock.prediction.portfolioquestion.PortfolioQuestionRecords.*;
/** Builds an allowlist from one stored valuation. Never forwards the original snapshot. */
public final class PortfolioQuestionFacts {
 public static final String PROMPT="portfolio-question-v2",KNOWLEDGE="portfolio-knowledge-v1",OUTPUT="portfolio-answer-v1";
 private PortfolioQuestionFacts(){}
 public static Facts build(JsonNode saved,String question,String model,ObjectMapper m){return build(saved,question,model,m,1800,98304);}
 public static Facts build(JsonNode saved,String question,String model,ObjectMapper m,int maxFacts,int maxBytes){try{var values=inspect(saved);if(saved.path("valuedCount").asInt()==0)throw PortfolioQuestionInput.unavailable();if(model==null||model.isBlank()||model.length()>128)throw PortfolioQuestionInput.evidence();String normalized=PortfolioQuestionInput.normalize(question);if(values.size()>Math.min(1800,maxFacts)||m.writeValueAsBytes(values).length>Math.min(98304,maxBytes))throw PortfolioQuestionInput.budget();
 var context=m.createObjectNode().put("sourceAnalysisId",saved.path("analysisId").asText()).put("sourceHash",saved.path("sourceHash").asText()).put("sourceCreatedAt",saved.path("createdAt").asText()).put("sourceBookRevision",saved.path("bookRevision").asText()).put("promptVersion",PROMPT).put("knowledgeVersion",KNOWLEDGE).put("outputVersion",OUTPUT).put("providerModel",model).put("question",normalized);context.set("facts",m.valueToTree(values));String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(m.writeValueAsBytes(context)));return new Facts(Collections.unmodifiableSortedMap(values),context,hash,PROMPT,model);
 }catch(BusinessException e){throw e;}catch(Exception e){throw PortfolioQuestionInput.evidence();}}
 static SortedMap<String,String> inspect(JsonNode saved){try{
 if(saved==null||!saved.isObject())throw PortfolioQuestionInput.evidence();PortfolioQuestionInput.uuid(text(saved,"analysisId"));Instant.parse(text(saved,"createdAt"));Instant.parse(text(saved,"capturedAt"));if(!text(saved,"sourceHash").matches("[a-f0-9]{64}")||!text(saved,"bookRevision").matches("0|[1-9][0-9]{0,18}")||!"portfolio-valuation-v1".equals(text(saved,"formulaVersion")))throw PortfolioQuestionInput.evidence();
 var asOf=LocalDate.parse(text(saved,"asOfDate"));String state=text(saved,"state"),freshness=text(saved,"freshness");if(!Set.of("EMPTY","PARTIAL","MIXED_DATES","COMPLETE").contains(state)||!Set.of("FRESH","STALE","UNKNOWN").contains(freshness)||!saved.path("mixedDates").isBoolean()||!saved.path("positionCount").isIntegralNumber()||!saved.path("valuedCount").isIntegralNumber())throw PortfolioQuestionInput.evidence();
 int count=saved.path("positionCount").intValue(),valued=saved.path("valuedCount").intValue();var lines=saved.path("lines");if(!lines.isArray()||count<0||count>100||lines.size()!=count||valued<0||valued>count)throw PortfolioQuestionInput.evidence();boolean complete="COMPLETE".equals(state);var f=new TreeMap<String,String>();f.put("AS_OF",asOf.toString());f.put("SAVED_AT",text(saved,"createdAt"));f.put("COVERAGE",valued+" / "+count+"只");f.put("COVERAGE_LIMIT",complete?"覆盖完整且价格同日，仅表示本次估值范围完整，不表示行情最新或安全":count==0?"本次没有持仓，不计算组合收益率或占比":"仅展示可估值部分合计，不代表完整组合，不计算完整占比和集中度");f.put("DATE_LIMIT",saved.path("mixedDates").asBoolean()?"各行价格来自不同交易日，不能视为同日完整组合":"实际价格日期须以各行记录为准，截止日不是每行成交日");f.put("FRESHNESS_LIMIT",switch(freshness){case "FRESH"->"按保存时日历核验，价格覆盖当次预期交易日，仍非实时行情";case "STALE"->"存在旧价格，不能称为当前市值";default->"无法确认行情是否覆盖最新预期交易日";});
 f.put("BASIS_LIMIT","按已保存未复权收盘价估算；浮盈不含分红、手续费、税费或已实现收益，不能保证未来收益");f.put("PROFIT_RULE","各行金额四舍五入到两位后加总；浮动盈亏为已舍入市值减成本金额");f.put("RETURN_RULE","成本收益率为浮动盈亏除以已舍入成本金额；成本为零时无法计算");f.put("CONCENTRATION_RULE","集中度仅表示单股市值占比是否超过配置阈值，不是完整风险评级，未超过也不等于安全");f.put("THRESHOLD",number(saved,"concentrationThresholdPercent",false)+"%");var threshold=new BigDecimal(number(saved,"concentrationThresholdPercent",false));if(threshold.signum()<=0||threshold.compareTo(new BigDecimal("100"))>0)throw PortfolioQuestionInput.evidence();
 var ordered=new ArrayList<JsonNode>();lines.forEach(ordered::add);ordered.sort(Comparator.comparing(n->n.path("instrumentId").asText()));var codes=new HashSet<String>();var ids=new HashSet<String>();var dates=new HashSet<LocalDate>();int available=0;String actualFreshness=count==0?"UNKNOWN":"FRESH";
 for(int i=0;i<ordered.size();i++){var l=ordered.get(i);String code=text(l,"instrumentId");if(!code.matches("(SH|SZ)[0-9]{6}")||!codes.add(code)||!ids.add(text(l,"positionId")))throw PortfolioQuestionInput.evidence();PortfolioQuestionInput.uuid(text(l,"positionId"));String key=String.format(Locale.ROOT,"S%04d_",i+1);f.put(key+"CODE",code);f.put(key+"COST",number(l,"costAmount",false));var q=l.path("quote");if(!code.equals(text(q,"instrumentId"))||!"RAW".equals(text(q,"priceBasis"))||!"baostock".equals(text(q,"provider")))throw PortfolioQuestionInput.evidence();String qf=text(q,"freshness");if(!Set.of("FRESH","STALE","UNKNOWN").contains(qf))throw PortfolioQuestionInput.evidence();if("UNKNOWN".equals(qf))actualFreshness="UNKNOWN";else if("STALE".equals(qf)&&!"UNKNOWN".equals(actualFreshness))actualFreshness="STALE";
 if("AVAILABLE".equals(text(q,"status"))){available++;var date=LocalDate.parse(text(q,"priceDate"));if(date.isAfter(asOf)||new BigDecimal(number(q,"close",false)).signum()<=0)throw PortfolioQuestionInput.evidence();dates.add(date);PortfolioQuestionInput.uuid(text(q,"versionId"));if(!text(q,"contentHash").matches("[a-f0-9]{64}"))throw PortfolioQuestionInput.evidence();f.put(key+"DATE",date.toString());f.put(key+"MARKET",number(l,"marketValue",false));String profit=number(l,"floatingProfit",true);f.put(key+"PROFIT",profit);f.put(key+"PROFIT_STATE",new BigDecimal(profit).signum()>0?"浮盈":new BigDecimal(profit).signum()<0?"浮亏":"浮动盈亏为零");f.put(key+"RETURN",optionalPercent(l,"returnPercent"));if(!q.path("retainedPrice").isBoolean())throw PortfolioQuestionInput.evidence();f.put(key+"PRICE_LIMIT",q.path("retainedPrice").asBoolean()?"停牌记录沿用上一次实际成交日收盘价":"使用本次保存的实际收盘价，非实时价格");
 if(complete&&!l.path("weightPercent").isNull()){f.put(key+"WEIGHT",number(l,"weightPercent",false)+"%");if(!l.path("concentrationTriggered").isBoolean())throw PortfolioQuestionInput.evidence();f.put(key+"CONCENTRATION",l.path("concentrationTriggered").booleanValue()?"超过本次配置的单股占比阈值":"未超过本次配置的单股占比阈值");}else if(!l.path("weightPercent").isNull()||!l.path("concentrationTriggered").isNull())throw PortfolioQuestionInput.evidence();
 }else if("UNAVAILABLE".equals(text(q,"status"))){if(!l.path("marketValue").isNull()||!l.path("floatingProfit").isNull()||!l.path("returnPercent").isNull()||!l.path("weightPercent").isNull()||!l.path("concentrationTriggered").isNull())throw PortfolioQuestionInput.evidence();String reason=text(q,"reason");if(!Set.of("NO_DATA","NO_VALID_CLOSE","CALENDAR_CONFLICT").contains(reason))throw PortfolioQuestionInput.evidence();f.put(key+"PRICE_LIMIT",switch(reason){case "NO_DATA"->"没有可用行情，未纳入估值小计";case "NO_VALID_CLOSE"->"没有有效收盘价，未纳入估值小计";default->"价格与交易日历冲突，未纳入估值小计";});}else throw PortfolioQuestionInput.evidence();}
 boolean mixed=dates.size()>1;String expected=count==0?"EMPTY":available<count?"PARTIAL":mixed?"MIXED_DATES":"COMPLETE";if(available!=valued||mixed!=saved.path("mixedDates").asBoolean()||!expected.equals(state)||!freshness.equals(actualFreshness))throw PortfolioQuestionInput.evidence();
 var subtotal=saved.path("subtotal");if(!subtotal.isObject())throw PortfolioQuestionInput.evidence();if(valued>0||count==0)amounts(f,"SUBTOTAL_",subtotal);else for(String k:List.of("costAmount","marketValue","floatingProfit","returnPercent"))if(!subtotal.path(k).isNull())throw PortfolioQuestionInput.evidence();
 if(complete){if(!saved.path("totals").isObject()||!saved.path("totals").equals(subtotal))throw PortfolioQuestionInput.evidence();amounts(f,"TOTAL_",saved.path("totals"));}else if(!saved.path("totals").isNull())throw PortfolioQuestionInput.evidence();return f;
 }catch(BusinessException e){throw e;}catch(Exception e){throw PortfolioQuestionInput.evidence();}}
 private static void amounts(Map<String,String> f,String prefix,JsonNode n){f.put(prefix+"COST",number(n,"costAmount",false));f.put(prefix+"MARKET",number(n,"marketValue",false));f.put(prefix+"PROFIT",number(n,"floatingProfit",true));f.put(prefix+"RETURN",optionalPercent(n,"returnPercent"));}
 private static String optionalPercent(JsonNode n,String k){if(n.path(k).isNull())return "无法计算：成本为零或没有可计算金额";return number(n,k,true)+"%";}
 private static String number(JsonNode n,String k,boolean negative){String t=text(n,k);if(!t.matches((negative?"-?":"")+"(?:0|[1-9][0-9]{0,38})(?:\\.[0-9]{1,6})?"))throw PortfolioQuestionInput.evidence();return t;}
 private static String text(JsonNode n,String k){var v=n.path(k);if(!v.isTextual()||v.textValue().isBlank()||v.textValue().length()>200)throw PortfolioQuestionInput.evidence();return v.textValue();}
}
